#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-commit-stamp.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * verify-commit-stamp — pre-commit gate that mechanizes the delegate-to-coder
 * rule by refusing commits that change `code/web/src/**` (or `<web-subdir>/src/**`)
 * behavior files without a fresh verifier Mode A stamp on every touched slice.
 *
 * Algorithm:
 *   1. Read staged paths (`git diff --cached --name-only`).
 *   2. Filter to <web>/src/** that are NOT under __specs__/, __tests__/,
 *      __manual__/, or __stories__/. These are the "behavior" files the
 *      coder writes; spec/test/manual edits are paired but not the gate target.
 *   3. For each behavior file, walk UP the directory tree to find the nearest
 *      __specs__/standards-compliance.yaml.
 *   4. Parse the lock: status MUST be "locked", verified MUST be "100%",
 *      last_validated MUST be valid ISO-8601 UTC, and (now - last_validated)
 *      MUST be within SAME_COMMIT_GRACE_MS (30 min; matches
 *      LOCK_FILES.yaml.verification.freshness_check).
 *   5. On any failure: BLOCK with file path + reason. Exit 1.
 *
 * Purpose: a behavior change without a recent verifier Mode A stamp means
 * the orchestrator skipped the feature-spec-writer → coder → verifier chain
 * and inlined. The 30-min window forces the verifier to have run within
 * the last half hour.
 *
 * Usage (wired into .git/hooks/pre-commit):
 *   node ~/.claude/standards/scripts/verify/verify-commit-stamp.mjs
 *
 * Env vars:
 *   WEB_SUBDIR — defaults to "code/web" per ROOT_LAYOUT.yaml.folder_layout.
 *                For turborepo apps, set WEB_SUBDIR="code/apps/<app>".
 *                For legacy repos that nest src/ at root, set WEB_SUBDIR="".
 *                Pre-2026-05-27 repos with /web/ at root: WEB_SUBDIR="web".
 */

import { execSync } from "node:child_process";
import { readFileSync, statSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";

function repoRoot() {
  try {
    return execSync("git rev-parse --show-toplevel", { encoding: "utf8" }).trim();
  } catch {
    process.stderr.write("\n❌ verify-commit-stamp: not in a git repo\n");
    process.exit(2);
  }
}

const REPO_ROOT = repoRoot();
const WEB_SUBDIR = process.env.WEB_SUBDIR ?? "code/web";
const SRC_PREFIX = WEB_SUBDIR ? `${WEB_SUBDIR}/src/` : "src/";
const SKIP_DIR_SEGMENTS = ["/__specs__/", "/__tests__/", "/__manual__/", "/__stories__/"];
const LOCK_FILENAME = "standards-compliance.yaml";
const SAME_COMMIT_GRACE_MS = 30 * 60 * 1000;

function readStagedPaths() {
  try {
    const out = execSync("git diff --cached --name-only", {
      cwd: REPO_ROOT,
      encoding: "utf8",
    });
    return out
      .split("\n")
      .map((s) => s.trim())
      .filter((s) => s.length > 0);
  } catch {
    return [];
  }
}

function findLockFor(behaviorFile) {
  let dir = dirname(join(REPO_ROOT, behaviorFile));
  while (dir.startsWith(REPO_ROOT)) {
    const candidate = join(dir, "__specs__", LOCK_FILENAME);
    try {
      statSync(candidate);
      return candidate;
    } catch {
      // not here; walk up
    }
    const parent = dirname(dir);
    if (parent === dir) return null;
    dir = parent;
  }
  return null;
}

function parseLock(path) {
  const content = readFileSync(path, "utf8");
  const status = (content.match(/^status:\s*(\S+)/m) || [])[1] || null;
  const verified = (content.match(/^verified:\s*"?([^"\n]+)"?/m) || [])[1] || null;
  const lastValidated = (content.match(/^last_validated:\s*(\S+)/m) || [])[1] || null;
  return { status, verified, lastValidated };
}

function block(violations) {
  process.stderr.write("");
  process.stderr.write("\nBLOCKED: commit refused by verify-commit-stamp\n\n");
  process.stderr.write(
    `  One or more ${SRC_PREFIX}** behavior files are staged without a fresh\n` +
    `  verifier Mode A stamp on the owning slice. The orchestrator MUST route\n` +
    `  writes through coder, then through verifier (Mode A), before commit.\n\n`,
  );
  for (const v of violations) {
    process.stderr.write(`  • ${v.file}\n`);
    process.stderr.write(`      reason: ${v.reason}\n`);
    if (v.lock) process.stderr.write(`      lock:   ${relative(REPO_ROOT, v.lock)}\n`);
  }
  process.stderr.write(
    `\n  Fix path: invoke the verifier in Mode A on each slice. On green, the\n` +
    `  verifier re-stamps the lock; re-attempt commit.\n\n` +
    `  This hook lives at .git/hooks/pre-commit (local only).\n\n`,
  );
}

const staged = readStagedPaths();
const behaviorFiles = staged.filter((p) => {
  if (!p.startsWith(SRC_PREFIX)) return false;
  if (!/\.(ts|tsx|mjs|js)$/.test(p)) return false;
  if (SKIP_DIR_SEGMENTS.some((seg) => p.includes(seg))) return false;
  return true;
});

if (behaviorFiles.length === 0) {
  process.exit(0);
}

const now = Date.now();
const violations = [];

for (const file of behaviorFiles) {
  const lock = findLockFor(file);
  if (lock === null) {
    violations.push({
      file,
      reason: "no __specs__/standards-compliance.yaml found in any ancestor folder",
      lock: null,
    });
    continue;
  }
  const { status, verified, lastValidated } = parseLock(lock);
  if (status !== "locked") {
    violations.push({
      file,
      reason: `lock status is "${status ?? "(missing)"}" — must be "locked"`,
      lock,
    });
    continue;
  }
  if (verified !== "100%") {
    violations.push({
      file,
      reason: `lock verified is "${verified ?? "(missing)"}" — must be "100%"`,
      lock,
    });
    continue;
  }
  if (lastValidated === null) {
    violations.push({ file, reason: "lock last_validated is missing", lock });
    continue;
  }
  const lastValidatedMs = Date.parse(lastValidated);
  if (Number.isNaN(lastValidatedMs)) {
    violations.push({
      file,
      reason: `lock last_validated "${lastValidated}" is not valid ISO-8601`,
      lock,
    });
    continue;
  }
  const ageMs = now - lastValidatedMs;
  if (ageMs > SAME_COMMIT_GRACE_MS) {
    const ageMin = Math.round(ageMs / 60000);
    violations.push({
      file,
      reason: `lock last_validated is ${ageMin} minutes old — must be within 30 min (verifier Mode A re-stamp required)`,
      lock,
    });
    continue;
  }
  if (ageMs < -60_000) {
    violations.push({
      file,
      reason: `lock last_validated is in the future by ${Math.round(-ageMs / 1000)}s — clock skew or bad stamp`,
      lock,
    });
    continue;
  }
}

if (violations.length > 0) {
  block(violations);
  process.exit(1);
}

process.stdout.write(
  `✅ verify-commit-stamp — ${behaviorFiles.length} behavior file(s) backed by fresh locks\n`,
);
process.exit(0);
